// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // locked block is N+1 on the reference; one block later settle is still forbidden
        vm.roll(block.number + 1);

        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok && address(c).balance == balBefore);
    }
}
